import{_ as o,o as c,c as d,a5 as t}from"./chunks/framework.DJo0M80U.js";const l=JSON.parse('{"title":"五、扩展知识点","description":"","frontmatter":{"title":"五、扩展知识点","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","Java基础","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第一部分：语言基础/01-基础语法/五、扩展知识点.md","filePath":"posts/java快速入门/第一部分：语言基础/01-基础语法/五、扩展知识点.md"}'),s={name:"posts/java快速入门/第一部分：语言基础/01-基础语法/五、扩展知识点.md"};function a(n,e,r,i,p,_){return c(),d("div",null,[...e[0]||(e[0]=[t("<div><p><code>+=</code>符号的扩展 下面的程序有问题吗？</p><p>public static void main(String[] args){ short s = 1; s+=1; System.out.println(s); } 分析： <code>s += 1</code> 逻辑上看作是 <code>s = s + 1</code> 计算结果被提升为<code>int</code>类型，再向<code>short</code>类型赋值时发生错误，因为不能将取值范围大的类型赋值到取值范围小的类型。但是， <code>s=s+1</code>进行两次运算 ， <code>+=</code> 是一个运算符，只运算一次，并带有强制转换的特点，也就是说 <code>s += 1</code> 就是 <code>s = (short)(s + 1)</code> ，因此程序没有问题编译通过，运行结果是<code>2.</code></p><p><strong>常量和变量的运算</strong> 下面的程序有问题吗？</p><p>public static void main(String[] args){ byte b1=1; byte b2=2; byte b3=1 + 2; byte b4=b1 + b2; System.out.println(b3); System.out.println(b4); } 分析： <code>b3 = 1 + 2</code> ， <code>1</code> 和 <code>2</code> 是常量，为固定不变的数据，在编译的时候（编译器<code>javac</code>），已经确定了 <code>1+2</code> 的结果并没有超过<code>byte</code>类型的取值范围，可以赋值给变量 <code>b3</code> ，因此 <code>b3=1 + 2</code> 是正确的。</p><p>反之， <code>b4 = b2 + b3</code> ， <code>b2</code> 和 <code>b3</code> 是变量，变量的值是可能变化的，在编译的时候，编译器<code>javac</code>不确定<code>b2+b3</code>的结果是什么，因此会将结果以<code>int</code>类型进行处理，所以<code>int</code>类型不能赋值给<code>byte</code>类型，因此编译失败。 在<code>jshell</code>中体现：</p></div>",1)])])}const m=o(s,[["render",a]]);export{l as __pageData,m as default};
